#!/usr/bin/env pwsh
$basedir=Split-Path $MyInvocation.MyCommand.Definition -Parent

$exe=""
$pathsep=":"
$env_node_path=$env:NODE_PATH
$new_node_path="D:\proyectos\Scrapping\node_modules\.pnpm\@nestjs+cli@10.4.9_esbuild@_f9ac2b1785538c470498743db0c73ae0\node_modules\@nestjs\cli\node_modules;D:\proyectos\Scrapping\node_modules\.pnpm\@nestjs+cli@10.4.9_esbuild@_f9ac2b1785538c470498743db0c73ae0\node_modules;D:\proyectos\Scrapping\node_modules\.pnpm\node_modules"
if ($PSVersionTable.PSVersion -lt "6.0" -or $IsWindows) {
  # Fix case when both the Windows and Linux builds of Node
  # are installed in the same directory
  $exe=".exe"
  $pathsep=";"
} else {
  $new_node_path="/proc/cygdrive/d/proyectos/Scrapping/node_modules/.pnpm/@nestjs+cli@10.4.9_esbuild@_f9ac2b1785538c470498743db0c73ae0/node_modules/@nestjs/cli/node_modules:/proc/cygdrive/d/proyectos/Scrapping/node_modules/.pnpm/@nestjs+cli@10.4.9_esbuild@_f9ac2b1785538c470498743db0c73ae0/node_modules:/proc/cygdrive/d/proyectos/Scrapping/node_modules/.pnpm/node_modules"
}
if ([string]::IsNullOrEmpty($env_node_path)) {
  $env:NODE_PATH=$new_node_path
} else {
  $env:NODE_PATH="$new_node_path$pathsep$env_node_path"
}

$ret=0
if (Test-Path "$basedir/node$exe") {
  # Support pipeline input
  if ($MyInvocation.ExpectingInput) {
    $input | & "$basedir/node$exe"  "$basedir/../../bin/nest.js" $args
  } else {
    & "$basedir/node$exe"  "$basedir/../../bin/nest.js" $args
  }
  $ret=$LASTEXITCODE
} else {
  # Support pipeline input
  if ($MyInvocation.ExpectingInput) {
    $input | & "node$exe"  "$basedir/../../bin/nest.js" $args
  } else {
    & "node$exe"  "$basedir/../../bin/nest.js" $args
  }
  $ret=$LASTEXITCODE
}
$env:NODE_PATH=$env_node_path
exit $ret
